SELECT CASE WHEN monthly_fee >= 225 THEN 'high' WHEN monthly_fee >= 96 THEN 'mid' ELSE 'low' END AS monthly_fee_bucket, QUARTER(end_date) AS end_quarter, ROUND((100 * SUM(CASE WHEN plan = 'premium' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_premium FROM subscriptions WHERE end_date BETWEEN '2023-09-01' AND '2024-03-14' GROUP BY CASE WHEN monthly_fee >= 225 THEN 'high' WHEN monthly_fee >= 96 THEN 'mid' ELSE 'low' END, QUARTER(end_date) HAVING ROUND((100 * SUM(CASE WHEN plan = 'premium' THEN 1 ELSE 0 END)) / COUNT(*), 1) >= 55 ORDER BY end_quarter DESC
